import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent bounded inverse, including all original random/damage/stun/publication instructions. */
public final class ShockCompanionDelta {
 static final String P="local/lito381/server/",N=P+"CombatCompanionSpells",H=P+"NativeShockCompanionAction",PC=P+"ClientSession",X=P+"CombatAccess";
 static ClassNode read(JarFile j,String n)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(n+".class"))).accept(c,ClassReader.SKIP_DEBUG|ClassReader.EXPAND_FRAMES);return c;}
 static AbstractInsnNode prev(AbstractInsnNode n){do{n=n.getPrevious();}while(n!=null&&n.getOpcode()<0);return n;}
 static AbstractInsnNode next(AbstractInsnNode n){do{n=n.getNext();}while(n!=null&&n.getOpcode()<0);return n;}
 static byte[] method(ClassNode c,MethodNode m,String name,int access){var q=new ClassNode();q.version=c.version;q.access=c.access;q.name=c.name;q.superName=c.superName;var copy=new MethodNode(access,name,m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(copy);q.methods.add(copy);var w=new ClassWriter(ClassWriter.COMPUTE_MAXS);q.accept(w);return w.toByteArray();}
 static InsnList legacyMaterial(MethodNode old){
  var consume=Arrays.stream(old.instructions.toArray()).filter(n->n instanceof MethodInsnNode v&&v.owner.equals(P+"CombatDatabase")&&v.name.equals("consumeMaterial")).findFirst().orElseThrow();var start=consume;while(!(start instanceof VarInsnNode v&&v.getOpcode()==ASTORE&&v.var==31))start=prev(start);while(!(start instanceof VarInsnNode begin&&begin.getOpcode()==ALOAD&&begin.var==0))start=prev(start);
  var labels=new HashMap<LabelNode,LabelNode>();for(var n:old.instructions)if(n instanceof LabelNode l)labels.put(l,new LabelNode());var x=new InsnList();for(var n=start;n!=consume.getNext();n=n.getNext())x.add(n.clone(labels));return x;
 }
 static void inverse(MethodNode m,MethodNode old){
  var param=Arrays.stream(m.instructions.toArray()).filter(n->n instanceof VarInsnNode v&&v.getOpcode()==ALOAD&&v.var==4).toList();if(param.size()!=1)throw new AssertionError("one frozen actor argument");var load=param.get(0);
  for(var n:m.instructions){if(n instanceof VarInsnNode v&&v.var>=5)v.var--;if(n instanceof IincInsnNode v&&v.var>=5)v.var--;if(n instanceof FrameNode f){if(!f.local.get(4).equals("java/lang/Object"))throw new AssertionError("bounded frame");f.local.remove(4);}}
  var resolve=new InsnList();resolve.add(new VarInsnNode(ALOAD,0));resolve.add(new LdcInsnNode("resolveBattleSpellCompanion"));resolve.add(new LdcInsnNode("(J)L"+PC+"$MassSlowCompanionTarget;"));resolve.add(new InsnNode(ICONST_1));resolve.add(new TypeInsnNode(ANEWARRAY,"java/lang/Object"));resolve.add(new InsnNode(DUP));resolve.add(new InsnNode(ICONST_0));resolve.add(new VarInsnNode(ALOAD,4));resolve.add(new MethodInsnNode(INVOKEVIRTUAL,P+"Protocol$AttackSpellRequest","targetObjectId","()J",false));resolve.add(new MethodInsnNode(INVOKESTATIC,"java/lang/Long","valueOf","(J)Ljava/lang/Long;",false));resolve.add(new InsnNode(AASTORE));resolve.add(new MethodInsnNode(INVOKESTATIC,X,"call","(Ljava/lang/Object;Ljava/lang/String;Ljava/lang/String;[Ljava/lang/Object;)Ljava/lang/Object;",false));m.instructions.insertBefore(load,resolve);m.instructions.remove(load);
  int monitors=0,available=0,admit=0,previous=0,following=0,nano=0;
  for(var n:m.instructions.toArray()){
   if(n.getOpcode()==POP&&prev(n)instanceof VarInsnNode v&&v.var==32){m.instructions.set(n,new InsnNode(v.getOpcode()==ASTORE?MONITORENTER:MONITOREXIT));monitors++;}
   if(n instanceof MethodInsnNode v){
    if(v.owner.equals(H)&&v.name.equals("available")){v.owner=N;available++;}
    if(v.owner.equals(H)&&v.name.equals("admit")){var expected=new int[]{ALOAD,ALOAD,ALOAD,ASTORE,ACONST_NULL,ASTORE,ACONST_NULL};for(int op:expected){var before=prev(n);if(before.getOpcode()!=op)throw new AssertionError("material admission shape");m.instructions.remove(before);}m.instructions.insertBefore(n,legacyMaterial(old));m.instructions.remove(n);admit++;}
    if(v.owner.equals(P+"NativeCastMaterial")&&(v.name.equals("previous")||v.name.equals("next"))){boolean isNext=v.name.equals("next");var store=next(n);if(!(store instanceof VarInsnNode s)||s.getOpcode()!=ASTORE||s.var!=(isNext?31:30)||!(prev(n)instanceof VarInsnNode receiver)||receiver.var!=0)throw new AssertionError("wire material snapshot");m.instructions.remove(prev(n));m.instructions.remove(store);m.instructions.remove(n);if(isNext)following++;else previous++;}
    if(v.owner.equals("java/lang/System")&&v.name.equals("nanoTime")&&next(n)instanceof VarInsnNode store&&store.getOpcode()==LSTORE&&store.var==26){var receiver=next(store);var key=next(receiver);if(receiver instanceof VarInsnNode r&&r.var==0&&key instanceof LdcInsnNode k&&k.cst.equals("cancelMeditation")){m.instructions.remove(store);m.instructions.remove(n);nano++;}}
   }
  }
  if(!List.of(monitors,available,admit,previous,following,nano).equals(List.of(5,4,1,1,1,1)))throw new AssertionError("bounded ports "+List.of(monitors,available,admit,previous,following,nano));m.desc=old.desc;m.maxLocals=old.maxLocals;
 }
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[0]);var candidate=new JarFile(a[1])){
  var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(old.entries())){names.add(e.getName());var n=candidate.getJarEntry(e.getName());if(n==null)throw new AssertionError("removed entry");if(!Arrays.equals(old.getInputStream(e).readAllBytes(),candidate.getInputStream(n).readAllBytes()))changed.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(candidate.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());if(!changed.equals(Set.of(N+".class",P+"NativeAreaMaterialAction.class"))||!fresh.equals(Set.of(H+".class",H+"$Death.class")))throw new AssertionError("archive boundary");
  var b=read(old,N);var c=read(candidate,N);if(c.fields.size()!=b.fields.size()||c.methods.size()!=b.methods.size()+1)throw new AssertionError("class shape");for(int i=0;i<b.fields.size();i++){var f=b.fields.get(i);var g=c.fields.get(i);if(!f.name.equals(g.name)||!f.desc.equals(g.desc)||f.access!=g.access||!Objects.equals(f.value,g.value))throw new AssertionError("field");}
  for(var original:b.methods){var m=c.methods.stream().filter(q->q.name.equals(original.name)&&q.desc.equals(original.desc)).findFirst().orElseThrow();if(original.name.equals("shock")&&Type.getArgumentTypes(original.desc).length==4){m=c.methods.stream().filter(q->q.name.equals("nativeShockCompanionBody")).findFirst().orElseThrow();inverse(m,original);}if(!Arrays.equals(method(b,original,original.name,original.access),method(c,m,original.name,original.access)))throw new AssertionError("original body differs "+original.name+original.desc);}
  var areaOld=read(old,P+"NativeAreaMaterialAction");var areaNext=read(candidate,P+"NativeAreaMaterialAction");if(areaNext.fields.size()!=areaOld.fields.size()||areaNext.methods.size()!=areaOld.methods.size()+1)throw new AssertionError("output helper schema");for(int i=0;i<areaOld.fields.size();i++){var f=areaOld.fields.get(i);var g=areaNext.fields.get(i);if(!f.name.equals(g.name)||!f.desc.equals(g.desc)||f.access!=g.access||!Objects.equals(f.value,g.value))throw new AssertionError("output helper field");}for(var original:areaOld.methods){String name=original.name.equals("captureOutput")?"nativeShockOriginalCaptureOutput":original.name;var m=areaNext.methods.stream().filter(q->q.name.equals(name)&&q.desc.equals(original.desc)).findFirst().orElseThrow();if(!Arrays.equals(method(areaOld,original,original.name,original.access),method(areaNext,m,original.name,original.access)))throw new AssertionError("other output helper method changed "+original.name);}
  var h=read(candidate,H);for(var f:h.fields)if(f.access!=(ACC_STATIC|ACC_FINAL)||!f.desc.equals("Ljava/lang/String;")||f.value==null)throw new AssertionError("stateful helper field");for(var m:h.methods)for(var n:m.instructions){if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW&&(t.desc.contains("Map")||t.desc.contains("Thread")||t.desc.contains("Executor")||t.desc.contains("ClassicWorldMonster")))throw new AssertionError("registry/worker/projection");if(n instanceof MethodInsnNode v&&(v.owner.startsWith("java/sql/")||v.owner.startsWith("java/nio/file/")||v.owner.contains("GameStateStore")||v.owner.contains("Executor")))throw new AssertionError("unexpected IO");}
 }System.out.println("PASS independent exact inverse: all original random/damage/stun/effect arithmetic and other methods/fields/archive unchanged; stateless bounded helper");}
}
